<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway;

use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;

class TemplateVersionCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(TemplateVersion $templateVersion, ?int $size): TemplateVersionCursor
    {
        $next = clone $this;
        $next->sinceUid = $templateVersion->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
